fn utf16(text: &str) -> Vec<u16> {
    text.encode_utf16().collect()
}

#[test]
fn oracle_edge_rows_match_the_port() {
    for &(line, expected) in ORACLE_EDGE {
        assert_eq!(run(line), expected, "{line}");
    }
}

#[test]
fn decode_reads_escapes_and_keeps_malformed_ones_literal() {
    assert_eq!(decode(r"\u0660\x41"), [0x660, 0x41]);
    assert_eq!(decode(r"\u00zz"), utf16(r"\u00zz"));
    assert_eq!(decode(r"\u12"), utf16(r"\u12"));
    assert_eq!(decode(r"\x4"), utf16(r"\x4"));
    assert_eq!(decode(r"\x4G"), utf16(r"\x4G"));
    assert_eq!(decode(r"\q"), utf16(r"\q"));
    assert_eq!(decode(r"\"), utf16(r"\"));
    assert_eq!(decode("é"), [0xc3, 0xa9]);
}

#[test]
fn escape_prints_printable_units_and_stops_at_nul() {
    assert_eq!(
        escape(&[0x41, 0x7e, 0x20, 0x7f, 0x1f, 0x660]),
        r"A~ \u007F\u001F\u0660"
    );
    assert_eq!(escape(&[0x41, 0, 0x42]), "A");
}

#[test]
fn format_mac_budget_and_absent_address() {
    assert_eq!(format_mac(Some(&[0xab, 0xcd]), 3), [0x41, 0x42, 0]);
    assert_eq!(format_mac(Some(&[1]), 5), [0x30, 0x31, 0]);
    assert_eq!(format_mac(Some(&[0xab]), 1), [0]);
    assert_eq!(format_mac(None, 3), [0]);
    assert!(format_mac(None, 0).is_empty());
    assert!(format_mac(Some(&[1]), 0).is_empty());
    assert_eq!(format_mac(Some(&[0x12, 0x34]), 4), [0x31, 0x32, 0x33, 0]);
}

#[test]
fn name_request_layout_and_capacity() {
    let packet = name_request(b"ABC", 0x1234, 0x21, false, b"SS", 271).unwrap();
    assert_eq!(packet.len(), 52);
    assert_eq!(packet[2..4], [0x01, 0x00]);
    assert_eq!(packet[48..50], [0x00, 0x21]);
    assert_eq!(packet[50..52], [0x00, 0x01]);

    let packet = name_request(b"ABC", 0x1234, 0x21, true, b"", 271).unwrap();
    assert_eq!(packet.len(), 50);
    assert_eq!(packet[2..4], [0x01, 0x10]);

    let scope = |len: usize| vec![b'S'; len];
    let length = |scope: &[u8], capacity| {
        name_request(b"ABC", 0, 0, false, scope, capacity).map(|packet| packet.len())
    };
    assert_eq!(length(&scope(220), 271), Some(270));
    assert_eq!(length(&scope(221), 271), Some(271));
    assert_eq!(length(&scope(222), 271), None);
    assert_eq!(length(&scope(0), 270), None);
}

#[test]
fn encode_name_pads_truncates_and_stops_at_nul() {
    let empty = encode_name(b"", b"");
    assert_eq!(empty.len(), 34);
    assert_eq!(empty[0], 32);
    assert_eq!(&empty[1..33], "CA".repeat(16).as_bytes());
    assert_eq!(empty[33], 0);

    let long = encode_name(&[b'A'; 17], &[b'S'; 300]);
    assert_eq!(long.len(), 289);
    assert_eq!(&long[1..33], "EB".repeat(16).as_bytes());

    assert_eq!(encode_name(b"A\0B", b"S\0T").len(), 35);
}

#[test]
fn dav_error_codes_and_required_lengths() {
    assert_eq!(DavError::InvalidParameter.win32_code(), 87);
    assert_eq!(DavError::BadNetName.win32_code(), 67);
    assert_eq!(
        DavError::InsufficientBuffer { required: 5 }.win32_code(),
        122
    );
    assert!(format!("{:?}", DavError::BadNetName).contains("BadNetName"));

    assert_eq!(
        http_from_unc(&utf16(r"\\server"), 13),
        Err(DavError::InsufficientBuffer { required: 14 })
    );
    assert_eq!(
        unc_from_http(&utf16("http://server/x"), 5),
        Err(DavError::InsufficientBuffer { required: 22 })
    );
    assert_eq!(
        http_from_unc(&[0x5c, 0x5c, 0x61, 0, 0x62], 512).map(|units| units.len()),
        Ok(9)
    );
}

