#[test]
fn server_name_checks() {
    assert_eq!(validate_servername(None), 0);
    assert_eq!(validate_servername(Some(utf16("").as_slice())), 53);
    assert_eq!(validate_servername(Some(utf16(r"\srv").as_slice())), 123);
    assert_eq!(validate_servername(Some(utf16(r"\").as_slice())), 123);
    assert_eq!(validate_servername(Some(utf16(r"\\").as_slice())), 123);
    assert_eq!(validate_servername(Some(utf16(r"\\srv").as_slice())), 0);
    assert_eq!(validate_servername(Some(utf16("srv").as_slice())), 0);
}

#[test]
fn samba_mappings() {
    assert_eq!(sd_control_to_samba(0x8000), 0);
    assert_eq!(sd_control_to_samba(0x7f3f), 0x7f3f);
    assert_eq!(sd_control_to_samba(0x0080), 0);

    assert_eq!(ace_type_to_samba(3), 3);
    assert_eq!(ace_type_to_samba(4), 0);

    // CONTAINER_INHERIT (0x02) maps to Samba's NO_PROPAGATE_INHERIT (0x04), as in the C code.
    assert_eq!(ace_flags_to_samba(0x02), 0x04);
    assert_eq!(ace_flags_to_samba(0x20), 0);
    assert_eq!(ace_flags_to_samba(0xdf), 0xdd);
    assert_eq!(ace_flags_to_samba(0), 0);

    assert_eq!(access_mask_to_samba(0xf000_0000), 0xf000_0000);
    assert_eq!(access_mask_to_samba(1), 0);
}

#[test]
fn wide_helpers_follow_the_c_string_rules() {
    assert_eq!(until_nul(&[0x41u16, 0, 0x42]), &[0x41u16]);
    assert_eq!(until_nul(&[0x41u16, 0x42]), &[0x41u16, 0x42]);
    assert_eq!(at(&[1u16, 2], 1), 2);
    assert_eq!(at(&[1u16, 2], 2), 0);

    for (c, space) in [
        (9u16, true),
        (13, true),
        (14, false),
        (0x61, false),
        (0x20, true),
    ] {
        assert_eq!(is_space(c), space, "{c:#x}");
    }

    assert!(eq_ci(&utf16("SSL"), "ssl"));
    assert!(!eq_ci(&utf16("ss"), "ssl"));
    assert!(!eq_ci(&utf16("ssa"), "ssl"));
    assert!(eq_ci(&utf16("Z["), "z["));
    assert!(!eq_ci(&utf16("@"), "`"));
    assert!(!eq_ci(&utf16("["), "{"));

    assert_eq!(decimal_digit(0x30), Some(0));
    assert_eq!(decimal_digit(0x39), Some(9));
    assert_eq!(decimal_digit(0x665), Some(5));
    assert_eq!(decimal_digit(0x669), Some(9));
    assert_eq!(decimal_digit(0x66a), None);
    assert_eq!(decimal_digit(0x61), None);
    assert_eq!(decimal_digit(0x2f), None);
    assert_eq!(decimal_digit(0xffff), None);
}

#[test]
fn wcstol_reads_signs_digits_and_clamps() {
    assert_eq!(wcstol_dec(&utf16("  -12x")), (-12, 5));
    assert_eq!(wcstol_dec(&utf16("+7")), (7, 2));
    assert_eq!(wcstol_dec(&utf16("abc")), (0, 0));
    assert_eq!(wcstol_dec(&utf16("-")), (0, 0));
    assert_eq!(wcstol_dec(&utf16("")), (0, 0));
    assert_eq!(wcstol_dec(&utf16("2147483648")), (i32::MAX, 10));
    assert_eq!(wcstol_dec(&utf16("-2147483649")), (i32::MIN, 11));
    assert_eq!(wcstol_dec(&utf16(&"9".repeat(26))), (i32::MAX, 26));
    assert_eq!(
        wcstol_dec(&utf16(&format!("-{}", "9".repeat(27)))),
        (i32::MIN, 28)
    );
    assert_eq!(wcstol_dec(&[0x661, 0x662]), (12, 2));
    assert_eq!(wcstol_dec(&utf16("0x1")), (0, 1));
}
